int[] v = {24, 3, 31, 9, 18, 14};
for (int p = 0; p < 2; p++) {
    int m = p;
    for (int j = p + 1; j < v.length; j++) {
        if (v[j] < v[m]) {
            m = j;
        }
    }
    int t = v[p];
    v[p] = v[m];
    v[m] = t;
}
String out = "";
for (int x : v) {
    out += x + " ";
}
System.out.println(out.trim());
```

